# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.contacts import contact_rows


class ContactRowTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            Student(
                "1", "Thistle", "Bram", "A", "bram@x.edu"
            ),
            Student(
                "2", "Quillon", "Sefa", "B", "sefa@x.edu"
            ),
            Student(
                "3", "Varrow", "Ines", "A", "ines@x.edu"
            )
        ]

    def test_sorted_by_display_name_and_aligned(self):
        self.assertEqual(
            contact_rows(self.students),
            [
                "Quillon, Sefa  B  sefa@x.edu",
                "Thistle, Bram  A  bram@x.edu",
                "Varrow, Ines   A  ines@x.edu"
            ]
        )

    def test_missing_email_names_the_student(self):
        extra = Student("4", "Orrin", "Sol", "C")
        with self.assertRaises(ValueError) as context:
            contact_rows(self.students + [extra])
        self.assertIn("Orrin, Sol", str(context.exception))

    def test_blank_email_counts_as_missing(self):
        lark = Student("5", "Lark", "Oren", "C", "")
        with self.assertRaises(ValueError) as context:
            contact_rows([lark])
        self.assertIn("Lark, Oren", str(context.exception))

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            contact_rows([])
